using Microsoft.Data.Sqlite;using Microsoft.AspNetCore.DataProtection;using Microsoft.AspNetCore.Identity;using Microsoft.Extensions.Options;using System.Security.Cryptography;using System.Text.Json;
namespace HomeLibrary;
public sealed class PatronCard {public string Id{get;set;}="";public string BorrowerId{get;set;}="";public string BorrowerUid{get;set;}="";public string IssuedAt{get;set;}="";public bool Revoked{get;set;}public bool ReviewRequired{get;set;}}
public sealed class PatronPin {public string BorrowerUid{get;set;}="";public string Hash{get;set;}="";public int Generation{get;set;}public int Failures{get;set;}public DateTimeOffset LockedUntil{get;set;}}
public sealed class KioskStation {public string Id{get;set;}="";public string Name{get;set;}="";public string TokenHash{get;set;}="";public DateTimeOffset Expires{get;set;}public bool Revoked{get;set;}}
public sealed class CardRegistry {public List<PatronCard> Cards{get;set;}=[];public List<PatronPin> Pins{get;set;}=[];public List<KioskStation> Stations{get;set;}=[];}
public sealed record KioskBorrower(string Station,string Card,string BorrowerUid,int PinGeneration,DateTimeOffset LastSeen);
public sealed class PatronCards:IDisposable {
 readonly object gate=new();readonly SqliteConnection db;readonly IDataProtector protect;readonly PasswordHasher<string> hasher=new(Options.Create(new PasswordHasherOptions{IterationCount=210000}));readonly string dummy;readonly TimeProvider clock;
 readonly Dictionary<string,(string Name,DateTimeOffset Expires)> pairing=[];readonly Dictionary<string,KioskBorrower> sessions=[];readonly string revocations;CardRegistry registry;
 public PatronCards(string directory,IDataProtectionProvider protection,bool restored=false,TimeProvider? time=null){clock=time??TimeProvider.System;protect=protection.CreateProtector("Carribrary.PatronCards.v1");db=new SqliteConnection($"Data Source={Path.Combine(directory,"patron-cards.sqlite")}");db.Open();using(var cmd=db.CreateCommand()){cmd.CommandText="PRAGMA journal_mode=WAL; PRAGMA secure_delete=ON; CREATE TABLE IF NOT EXISTS registry(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);";cmd.ExecuteNonQuery();cmd.CommandText="SELECT data FROM registry WHERE id=1";var data=cmd.ExecuteScalar() as string;registry=data==null?new():JsonSerializer.Deserialize<CardRegistry>(protect.Unprotect(data),Library.Json)??new();}
  dummy=hasher.HashPassword("dummy","000000");revocations=Path.Combine(directory,"card-revocations.txt");
  var revoked=File.Exists(revocations)?File.ReadAllLines(revocations).ToHashSet():[];foreach(var card in registry.Cards)if(revoked.Contains(Hash(card.Id)))card.Revoked=true;
  if(restored){foreach(var station in registry.Stations)station.Revoked=true;foreach(var card in registry.Cards.Where(c=>!c.Revoked))card.ReviewRequired=true;}Save();
 }
 static string Token()=>Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).TrimEnd('=').Replace('+','-').Replace('/','_');
 static string Hash(string token)=>Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(token??"")));
 static string Code(string value){var code=(value??"").Trim();const string prefix="carribrary:card:v1:";if(code.StartsWith(prefix,StringComparison.Ordinal))code=code[prefix.Length..];return System.Text.RegularExpressions.Regex.IsMatch(code,@"^[A-Za-z0-9_-]{43}$")?code:"";}
 void Save(){using var cmd=db.CreateCommand();cmd.CommandText="INSERT INTO registry VALUES(1,$data) ON CONFLICT(id) DO UPDATE SET data=$data";cmd.Parameters.AddWithValue("$data",protect.Protect(JsonSerializer.Serialize(registry,Library.Json)));cmd.ExecuteNonQuery();}
 PatronCard Active(Store store,string code){var card=registry.Cards.Find(c=>c.Id==Code(code)&&!c.Revoked&&!c.ReviewRequired)??throw new LibraryError("Card or verification is unavailable. Ask the librarian.",403);var b=store.Read().State.Borrowers.Find(b=>b.Id==card.BorrowerId&&b.BorrowerUid==card.BorrowerUid&&!b.Archived);if(b==null)throw new LibraryError("Card or verification is unavailable. Ask the librarian.",403);return card;}
 public object List(Store store){lock(gate){var s=store.Read().State;return new{cards=registry.Cards.Where(c=>s.Borrowers.Any(b=>b.Id==c.BorrowerId&&b.BorrowerUid==c.BorrowerUid)).Select(c=>new{c.Id,c.BorrowerId,c.IssuedAt,c.Revoked,c.ReviewRequired,pinSet=registry.Pins.Any(p=>p.BorrowerUid==c.BorrowerUid)}).ToArray(),stations=registry.Stations.Select(s=>new{s.Id,s.Name,s.Expires,s.Revoked}).ToArray()};}}
 public object Issue(Store store,string borrowerId,string pin){lock(gate){var b=SelfService.Borrower(store.Read().State,borrowerId);if(pin!="")SetPin(b.BorrowerUid,pin);foreach(var c in registry.Cards.Where(c=>c.BorrowerUid==b.BorrowerUid&&!c.Revoked))Revoke(c);var card=new PatronCard{Id=Token(),BorrowerId=b.Id,BorrowerUid=b.BorrowerUid,IssuedAt=clock.GetUtcNow().ToString("O")};registry.Cards.Add(card);Save();return new{card.Id,card.BorrowerId,card.IssuedAt,code="carribrary:card:v1:"+card.Id};}}
 void SetPin(string uid,string pin){if(!System.Text.RegularExpressions.Regex.IsMatch(pin??"",@"^\d{6,12}$"))throw new LibraryError("Choose a private PIN of 6–12 digits; give it to the borrower separately from the card.");var p=registry.Pins.Find(p=>p.BorrowerUid==uid);if(p==null){p=new(){BorrowerUid=uid};registry.Pins.Add(p);}p.Hash=hasher.HashPassword(uid,pin!);p.Generation++;p.Failures=0;p.LockedUntil=default;}
 public void ResetPin(Store store,string borrower,string pin){lock(gate){SetPin(SelfService.Borrower(store.Read().State,borrower).BorrowerUid,pin);Save();}}
 void Revoke(PatronCard card){card.Revoked=true;Directory.CreateDirectory(Path.GetDirectoryName(revocations)!);File.AppendAllText(revocations,Hash(card.Id)+"\n");if(OperatingSystem.IsLinux())File.SetUnixFileMode(revocations,UnixFileMode.UserRead|UnixFileMode.UserWrite);}
 public void ChangeCard(string id,string action){lock(gate){var card=registry.Cards.Find(c=>c.Id==id)??throw new LibraryError("Card not found.");if(action=="revoke")Revoke(card);else if(action=="review"&&!card.Revoked)card.ReviewRequired=false;else throw new LibraryError("Revoked cards cannot be reactivated. Issue a replacement.");Save();}}
 public object Resolve(Store store,string code){lock(gate){var card=Active(store,code);return new{borrowerId=card.BorrowerId};}}
 public object? Digital(Store store,string borrowerId){lock(gate){var b=SelfService.Borrower(store.Read().State,borrowerId);var c=registry.Cards.LastOrDefault(c=>c.BorrowerUid==b.BorrowerUid&&!c.Revoked&&!c.ReviewRequired);return c==null?null:new{c.Id,c.BorrowerId,name=b.Name,code="carribrary:card:v1:"+c.Id};}}
 public object Pair(Store store,string name){lock(gate){if(!store.Read().State.SelfService.Kiosk)throw new LibraryError("Enable Self-service kiosk first.",403);name=(name??"").Trim();if(name.Length is <1 or >80||name.Any(char.IsControl))throw new LibraryError("Give this kiosk a name up to 80 characters.");foreach(var key in pairing.Where(p=>p.Value.Expires<clock.GetUtcNow()).Select(p=>p.Key).ToArray())pairing.Remove(key);if(pairing.Count>=20)throw new LibraryError("Wait for outstanding pairing codes to expire.");var code=RandomNumberGenerator.GetInt32(10000000,100000000).ToString();pairing[Hash(code)]=(name,clock.GetUtcNow().AddMinutes(10));return new{code,expiresInSeconds=600};}}
 public string Enroll(Store store,string code){lock(gate){if(!store.Read().State.SelfService.Kiosk||!pairing.Remove(Hash(code),out var p)||p.Expires<clock.GetUtcNow())throw new LibraryError("Kiosk pairing code is invalid or expired.",403);if(registry.Stations.Count(s=>!s.Revoked)>=100)throw new LibraryError("Revoke an unused kiosk before adding another.");var token=Token();registry.Stations.Add(new(){Id=Guid.NewGuid().ToString("N"),Name=p.Name,TokenHash=Hash(token),Expires=clock.GetUtcNow().AddDays(30)});Save();return token;}}
 KioskStation Station(Store store,string? token){if(!store.Read().State.SelfService.Kiosk)throw new LibraryError("Self-service kiosks are disabled.",403);return registry.Stations.Find(s=>!s.Revoked&&s.Expires>clock.GetUtcNow()&&s.TokenHash==Hash(token??""))??throw new LibraryError("This kiosk needs librarian authorization.",401);}
 public void RevokeStation(string id){lock(gate){var station=registry.Stations.Find(s=>s.Id==id)??throw new LibraryError("Kiosk not found.");station.Revoked=true;Save();}}
 public object StationStatus(Store store,string? token){lock(gate){var station=Station(store,token);return new{station.Name};}}
 public (string Token,object View) Verify(Store store,string? stationToken,string code,string pin){lock(gate){var station=Station(store,stationToken);PatronCard? card=null;try{card=Active(store,code);}catch(LibraryError){}var record=registry.Pins.Find(p=>p.BorrowerUid==card?.BorrowerUid);var correct=hasher.VerifyHashedPassword(card?.BorrowerUid??"dummy",record?.Hash??dummy,pin??"")!=PasswordVerificationResult.Failed;
  if(card==null||record==null||record.LockedUntil>clock.GetUtcNow()||!correct){if(record!=null&&record.LockedUntil<=clock.GetUtcNow()){record.Failures++;if(record.Failures>=5){record.LockedUntil=clock.GetUtcNow().AddMinutes(15);record.Failures=0;}Save();}throw new LibraryError("Card or PIN could not be verified. Wait before retrying or ask the librarian.",403);}
  record.Failures=0;Save();foreach(var key in sessions.Where(x=>x.Value.Station==station.Id||x.Value.LastSeen.AddMinutes(5)<clock.GetUtcNow()).Select(x=>x.Key).ToArray())sessions.Remove(key);var token=Token();sessions[Hash(token)]=new(station.Id,card.Id,card.BorrowerUid,record.Generation,clock.GetUtcNow());var b=SelfService.Borrower(store.Read().State,card.BorrowerId);return (token,new{name=b.Name.Split(' ')[0]});
 }}
 public object AsBorrower(Store store,string? stationToken,string? sessionToken,Func<string,string,object> action){lock(gate){return store.Locked(_=>{var station=Station(store,stationToken);var key=Hash(sessionToken??"");if(!sessions.TryGetValue(key,out var session)||session.Station!=station.Id||session.LastSeen.AddSeconds(store.Read().State.SelfService.IdleSeconds)<clock.GetUtcNow()){sessions.Remove(key);throw new LibraryError("Your kiosk session ended. Scan your card and verify again.",401);}var card=Active(store,session.Card);var pin=registry.Pins.Find(p=>p.BorrowerUid==session.BorrowerUid);if(pin?.Generation!=session.PinGeneration)throw new LibraryError("Your PIN changed. Start again.",401);sessions[key]=session with{LastSeen=clock.GetUtcNow()};return action(card.BorrowerId,station.Id);});}}
 public void End(string? token){lock(gate)sessions.Remove(Hash(token??""));}
 public void PruneDeleted(Store store){lock(gate){var live=store.Read().State;var known=live.Borrowers.Select(b=>b.BorrowerUid).Concat(live.RecycleBin.Where(x=>x.Borrower!=null).Select(x=>x.Borrower!.BorrowerUid)).ToHashSet();var removed=registry.Cards.Where(c=>!known.Contains(c.BorrowerUid)).ToArray();foreach(var c in removed)Revoke(c);registry.Cards.RemoveAll(c=>!known.Contains(c.BorrowerUid));registry.Pins.RemoveAll(p=>!known.Contains(p.BorrowerUid));foreach(var key in sessions.Where(x=>!known.Contains(x.Value.BorrowerUid)).Select(x=>x.Key).ToArray())sessions.Remove(key);Save();}}
 public void Dispose()=>db.Dispose();
}
